using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading;using System.Threading.Tasks;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
using Microsoft.Extensions.DependencyInjection;using PhotoBooth.Core.Models;using PhotoBooth.Core.Services;using PhotoBooth.Core.Pipelines;using PhotoBooth.Customer.UI.ViewModels;using PhotoBooth.Customer.UI.Workflow;
class PrintPolicyEntry { [STAThread]static void Main(string[] args)=>UnifiedUxCheck.PrintPolicyMain(args); }
partial class UnifiedUxCheck {
 public static void PrintPolicyMain(string[] args){output=Path.GetFullPath(args[0]);Directory.CreateDirectory(output);app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};foreach(var theme in new[]{"DarkTheme","Icons"})app.Resources.MergedDictionaries.Add((ResourceDictionary)Application.LoadComponent(new Uri("/MiuPhotoBooth;component/Themes/"+theme+".xaml",UriKind.Relative)));SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());app.Dispatcher.BeginInvoke(new Action(async()=>{try{await RunPrintPolicy();Console.WriteLine("ALL X74 PRINT CHECKS PASS: "+checks);}catch(Exception e){Console.WriteLine(e);Environment.ExitCode=1;}finally{app.Shutdown();}}));app.Run();}
 static void SetField(object target,string name,object value)=>target.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(target,value);
 static async Task RunPrintPolicy(){
  var p=await Provider(new Camera(),new Live(),new Auth());var vm=p.GetRequiredService<FrameSelectionViewModel>();var context=p.GetRequiredService<CustomerWorkflowContext>();var machine=p.GetRequiredService<CustomerWorkflowStateMachine>();
  var sink=new PrintSink();var printer=new PolicyPrinter();SetField(vm,"printPipeline",sink);SetField(vm,"printers",printer);SetField(vm,"sessions",new PolicySessions());
  var frame=new PhotoBooth.Core.Models.Frame{Id=Guid.NewGuid(),Name="Khoảnh khắc của bạn",SourcePath=Path.GetFullPath("Scripts/Validation/Fixtures/ApprovedUx/frame-0.png"),PixelWidth=600,PixelHeight=900,Slots=new[]{new FrameSlot{Index=0,X=30,Y=30,Width=259,Height=366}}};
  vm.SelectedFrame=frame;vm.FrameSlots[0].Photo=new CapturedPhotoChoice(Path.GetFullPath("Scripts/Validation/Fixtures/ApprovedUx/photo-0.png"),1);
  var view=new PhotoBooth.Customer.UI.Views.FrameSelectionView{DataContext=vm};
  foreach(var type in new[]{BoothAccessCodeType.PhotoBooth,BoothAccessCodeType.SelfBooth,BoothAccessCodeType.Event}){
   context.Authorization=new BoothAccessAuthorization{CodeType=type,Settings=new BoothAccessSettings{PrintCopies=3}};context.RequestedPrintCopies=3;context.MaximumPrintCopies=10;context.PrintPolicyMode=EventPrintPolicyMode.Manual;context.PrintingEnabled=true;
   typeof(FrameSelectionViewModel).GetProperty("PrintingEnabled").SetValue(vm,true);vm.PrintCopies=9;
   Check(vm.PrintCopies==(type==BoothAccessCodeType.Event?9:3),"package cannot override quantity "+type);vm.IncreaseCopiesCommand.Execute(null);Check(vm.PrintCopies==(type==BoothAccessCodeType.Event?10:3),"increment guarded "+type);
   Check(vm.CanChangePrintCopies==(type==BoothAccessCodeType.Event),"quantity visibility "+type);Check(vm.CanSkipPrint==(type==BoothAccessCodeType.SelfBooth),"skip only SelfBooth "+type);
   ((Border)view.FindName("Confirmation")).Visibility=Visibility.Visible;
   foreach(var size in new[]{new[]{1366,768},new[]{900,1600},new[]{600,1067}}){await Render(view,"confirmation-"+type+"-"+size[0],size[0],size[1]);var quantity=Descendants(view).OfType<TextBlock>().Single(x=>x.Text=="Số bản in");Check(((StackPanel)quantity.Parent).Visibility==(type==BoothAccessCodeType.Event?Visibility.Visible:Visibility.Collapsed),"actual quantity control "+type);}
  }
  context.Authorization.CodeType=BoothAccessCodeType.SelfBooth;context.RequestedPrintCopies=3;vm.PrintCopies=8;typeof(FrameSelectionViewModel).GetProperty("PrintingEnabled").SetValue(vm,true);
  await ButtonStates(view,Descendants(view).OfType<Button>().Single(x=>Equals(x.Content,"Bỏ qua in")),"selfbooth-skip");
  context.BoothSession=new BoothSession{Id=Guid.NewGuid(),Status=BoothSessionStates.Finalizing};context.DeliverableId="fixture-ready";context.ConnectedPrinterId=printer.Profile.PrinterId;context.ConnectedPrinterProfileId=printer.Profile.Id;
  typeof(CustomerWorkflowStateMachine).GetProperty("State").SetValue(machine,CustomerWorkflowState.FrameSelection);
  Check(vm.SkipPrintCommand.CanExecute(null),"skip executable");vm.SkipPrintCommand.Execute(null);await Wait(()=>!vm.IsPrinting,"skip finishes");Check(machine.State==CustomerWorkflowState.Complete&&sink.Copies.Count==0,"skip finishes without a print call");
  typeof(CustomerWorkflowStateMachine).GetProperty("State").SetValue(machine,CustomerWorkflowState.FrameSelection);vm.PrintCommand.Execute(null);await Wait(()=>!vm.IsPrinting,"normal finishes");Check(machine.State==CustomerWorkflowState.Complete&&sink.Copies.SequenceEqual(new[]{3}),"printing resets prior skip and sends exactly package quantity");
  context.RequestedPrintCopies=0;vm.PrintCopies=9;context.PrintingEnabled=false;typeof(FrameSelectionViewModel).GetProperty("PrintingEnabled").SetValue(vm,false);Check(vm.PrintCopies==0&&!vm.CanSkipPrint&&!vm.CanChangePrintCopies,"zero package cannot create a print");
  typeof(CustomerWorkflowStateMachine).GetProperty("State").SetValue(machine,CustomerWorkflowState.FrameSelection);vm.PrintCommand.Execute(null);await Wait(()=>!vm.IsPrinting,"zero finishes");Check(sink.Copies.Count==1,"zero-copy package finishes without printing");await vm.ShutdownAsync();
 }
 sealed class PrintSink:IPrintPipeline{public List<int>Copies=new List<int>();public Task ExecuteAsync(Guid s,Guid p,int n,CancellationToken t){Copies.Add(n);return Task.CompletedTask;}}
 sealed class PolicySessions:IBoothSessionService{public Task<BoothSession>StartAsync(Guid e,Guid? p,CancellationToken t)=>throw new NotSupportedException();public Task<BoothSession>GetAsync(Guid id,CancellationToken t)=>throw new NotSupportedException();public Task UpdateAsync(BoothSession s,CancellationToken t)=>Task.CompletedTask;public Task CompleteAsync(BoothSession s,CancellationToken t)=>Task.CompletedTask;public Task AbandonAsync(BoothSession s,string r,CancellationToken t)=>Task.CompletedTask;public Task ReplaceCapturedShotAsync(Guid s,string id,CapturedShot r,CancellationToken t)=>Task.CompletedTask;public Task ReplaceCapturedShotsAsync(Guid s,IReadOnlyDictionary<string,CapturedShot>r,CancellationToken t)=>Task.CompletedTask;}
 sealed class PolicyPrinter:IPrinterService{public PrinterProfile Profile=new PrinterProfile{Id=Guid.NewGuid(),PrinterId="fixture",PrinterName="Máy in kiểm thử",IsDefault=true};public Task<IReadOnlyList<string>>GetPrintersAsync(CancellationToken t)=>Task.FromResult<IReadOnlyList<string>>(new[]{"fixture"});public Task<IReadOnlyList<DiscoveredPrinter>>ScanAsync(CancellationToken t)=>Task.FromResult<IReadOnlyList<DiscoveredPrinter>>(new DiscoveredPrinter[0]);public Task<DiscoveredPrinter>ConnectAsync(string id,CancellationToken t)=>Task.FromResult(new DiscoveredPrinter{Id=Profile.PrinterId,Name=Profile.PrinterName});public Task<bool>IsConnectedAsync(string id,CancellationToken t)=>Task.FromResult(true);public Task<IReadOnlyList<PrinterProfile>>GetProfilesAsync(CancellationToken t)=>Task.FromResult<IReadOnlyList<PrinterProfile>>(new[]{Profile});public Task SaveProfileAsync(PrinterProfile p,CancellationToken t)=>Task.CompletedTask;public Task DeleteProfileAsync(Guid id,CancellationToken t)=>Task.CompletedTask;public Task PrintAsync(PrintJob j,CancellationToken t)=>throw new Exception("No real hardware in this fixture");}
}
